return {["fb307_01"]={["down"]=[[fb307_02]],["dsc"]=[[这里是论剑坡。越往上走,山路越陡。一阵微风吹来,一旁的树沙沙作响,仿佛在说悄悄话。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_01]],["name"]=[[论剑坡]],["permission"]=1,["role1"]=[[fb307_01]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb307_02"]={["down"]=[[fb307_03]],["dsc"]=[[登山之路则在其山脊之上，山路崎岖难行，两侧脊坡光滑挺拔，若有失足，便可能摔落山崖。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_02]],["name"]=[[山脊]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb307_01]],["visible"]=1},["fb307_03"]={["down"]=[[fb307_07]],["dsc"]=[[栈道悬于高空，所经之处，景色无不俊秀壮观，走在其上，如履平地，叫人不得不感叹这巧夺天工的建造。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_03]],["item1"]=[[fbwp01]],["name"]=[[栈道]],["permission"]=1,["right"]=[[fb307_04]],["stepMusic"]=[[jiaobu]],["up"]=[[fb307_02]],["visible"]=1},["fb307_04"]={["dsc"]=[[路上是用青石板铺成的石阶，路边偶尔长有荆棘，一不小心就会被划伤了。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_04]],["left"]=[[fb307_03]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb307_05]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb307_05"]={["dsc"]=[[路上是用青石板铺成的石阶，路边偶尔长有荆棘，一不小心就会被划伤了。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_05]],["left"]=[[fb307_04]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb307_06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb307_06"]={["dsc"]=[[只见左右上下都是陡峭的岩石，滑滑的难以着手。脚下就是万丈悬崖，吓得人不敢下望。山风罡烈，直要把你吹了下去。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_06]],["left"]=[[fb307_05]],["name"]=[[山崖]],["permission"]=1,["role1"]=[[fb307_02]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb307_07"]={["down"]=[[fb307_08]],["dsc"]=[[栈道悬于高空，所经之处，景色无不俊秀壮观，走在其上，如履平地，叫人不得不感叹这巧夺天工的建造。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"]=[[fb307_07]],["item1"]=[[fbwp02]],["name"]=[[栈道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb307_03]],["visible"]=1},["fb307_08"]={["down"]=[[fb307_09]],["dsc"]=[[栈道悬于高空，所经之处，景色无不俊秀壮观，走在其上，如履平地，叫人不得不感叹这巧夺天工的建造。]],["enterfb203_ble"]=1,["fightBackground"]=[[山内]],["id"